theorem quaternionSymbolSplit_baseChange [Field F] [Field K] [Algebra F K] {u v : F}
    (h : QuaternionSymbolSplit u v) :
    QuaternionSymbolSplit (algebraMap F K u) (algebraMap F K v)

theorem quaternionSymbolSplit_mul_norm_right [Field F] {u v n α β : F}
    (hn : n = α ^ 2 - u * β ^ 2) (hn0 : n ≠ 0) :
    QuaternionSymbolSplit u v → QuaternionSymbolSplit u (v * n)

theorem quaternionSymbolSplit_mul_norm_right_iff [Field F] {u v n α β : F}
    (hn : n = α ^ 2 - u * β ^ 2) (hn0 : n ≠ 0) :
    QuaternionSymbolSplit u (v * n) ↔ QuaternionSymbolSplit u v

theorem quaternionSymbolSplit_mul_norm_left_iff [Field F] {u v n α β : F}
    (hn : n = α ^ 2 - v * β ^ 2) (hn0 : n ≠ 0) :
    QuaternionSymbolSplit (u * n) v ↔ QuaternionSymbolSplit u v

theorem isotropic_of_pos_of_neg [Fintype ι] (a : ι → K) {i j : ι}
    (hi : 0 < a i) (hj : a j < 0) :
    Isotropic a

theorem zero_or_pos_neg_of_isotropic [Fintype ι] {a : ι → K}
    (h : Isotropic a) :
    (∃ i, a i = 0) ∨ ∃ i j, 0 < a i ∧ a j < 0

theorem all_pos_or_all_neg_of_not_isotropic [Fintype ι] [Nonempty ι] {a : ι → K}
    (hreg : ∀ i, a i ≠ 0) (haniso : ¬ Isotropic a) :
    (∀ i, 0 < a i) ∨ (∀ i, a i < 0)

theorem not_isotropic_of_all_pos [Fintype ι] {a : ι → K}
    (hpos : ∀ i, 0 < a i) :
    ¬ Isotropic a

theorem not_isotropic_of_all_neg [Fintype ι] {a : ι → K}
    (hneg : ∀ i, a i < 0) :
    ¬ Isotropic a

theorem isotropic_of_zero_coeff [Field F] [Fintype ι] (a : ι → F) {i : ι}
    (hi : a i = 0) :
    Isotropic a

theorem isotropic_mul_square [Field F] [Fintype ι] {a u : ι → F}
    (hu : ∀ i, u i ≠ 0) :
    Isotropic (fun i => a i * u i ^ 2) ↔ Isotropic a

theorem ternary_isotropic_one_of_isSquare_neg_left [Field F] {b c : F}
    (hb : IsSquare (-b)) :
    TernaryIsotropic 1 b c

theorem ternary_isotropic_one_of_isSquare_neg_right [Field F] {b c : F}
    (hc : IsSquare (-c)) :
    TernaryIsotropic 1 b c

theorem alpha_integral (E : Intermediate F) {a : E.carrier} {α : Ω}
    (hα : α ^ 2 = (a : Ω)) :
    IsIntegral E.carrier α

theorem minpoly_alpha_eq (E : Intermediate F) {a : E.carrier} {α : Ω}
    (hα : α ^ 2 = (a : Ω)) (hnsq : ¬ IsSquare a) :
    minpoly E.carrier α = X ^ 2 - C a

theorem exists_root_over_intermediate (E : Intermediate F) {p : E.carrier[X]}
    (hp : p.degree ≠ 0) :
    ∃ α : Ω, Polynomial.eval₂ (algebraMap E.carrier Ω) α p = 0

theorem chain_carrier_directed {s : Set (Intermediate F)}
    (hs : IsChain (· ≤ ·) s) :
    Directed (· ≤ ·) (fun E : s => E.1.carrier)

theorem finiteSameStrictSignOrdering_of_hom_all_pos
    {R : Type u} [Field R] {ι : Type w}
    {K : Type v} [Field K] [LinearOrder K] [IsStrictOrderedRing K]
    (f : RatFunc R →+* K) {a : ι → RatFunc R}
    (hpos : ∀ i, 0 < f (a i)) :
    FiniteSameStrictSignOrdering a

theorem finiteSameStrictSignOrdering_of_hom_all_neg
    {R : Type u} [Field R] {ι : Type w}
    {K : Type v} [Field K] [LinearOrder K] [IsStrictOrderedRing K]
    (f : RatFunc R →+* K) {a : ι → RatFunc R}
    (hneg : ∀ i, f (a i) < 0) :
    FiniteSameStrictSignOrdering a

theorem hasNormalizedSignObstruction_polynomial_mul_square
    {R : Type u} [Field R] {B C S T : Polynomial R}
    (hS : S ≠ 0) (hT : T ≠ 0) :
    HasNormalizedSignObstruction.{u, v}
        (algebraMap (Polynomial R) (RatFunc R) (B * S ^ 2))
        (algebraMap (Polynomial R) (RatFunc R) (C * T ^ 2)) ↔
      HasNormalizedSignObstruction.{u, v}
        (algebraMap (Polynomial R) (RatFunc R) B)
        (algebraMap (Polynomial R) (RatFunc R) C)

private theorem baseSquareSubsemiring_le_baseSquareWeightedSubsemiring :
    baseSquareSubsemiring (F := F) (K := K) ≤
      baseSquareWeightedSubsemiring (F := F) (K := K)

theorem le_linearOrderOfIsOrdering_iff
    (P : _root_.RingPreordering F) [P.IsOrdering] {x y : F} :
    @LE.le F (linearOrderOfIsOrdering P).toLE x y ↔ y - x ∈ P

theorem lt_linearOrderOfIsOrdering_iff
    (P : _root_.RingPreordering F) [P.IsOrdering] {x y : F} :
    @LT.lt F (linearOrderOfIsOrdering P).toLT x y ↔ y - x ∈ P ∧ x - y ∉ P

theorem zero_le_linearOrderOfIsOrdering_iff
    (P : _root_.RingPreordering F) [P.IsOrdering] {x : F} :
    @LE.le F (linearOrderOfIsOrdering P).toLE 0 x ↔ x ∈ P

theorem zero_lt_linearOrderOfIsOrdering_iff
    (P : _root_.RingPreordering F) [P.IsOrdering] {x : F} :
    @LT.lt F (linearOrderOfIsOrdering P).toLT 0 x ↔ x ∈ P ∧ -x ∉ P

theorem isStrictOrderedRingOfIsOrdering
    (P : _root_.RingPreordering F) [P.IsOrdering] :
    @IsStrictOrderedRing F _ (linearOrderOfIsOrdering P).toPartialOrder

theorem FinitePolynomialState.eval_ne_zero_of_not_mem_realRoots
    {R : Type u} [Field R] {ι : Type*} [Fintype ι]
    {a : ι → _root_.RatFunc R}
    (T : FinitePolynomialState a) {r : R}
    (hr : r ∉ T.realRoots) (i : ι) :
    (T.A i).eval r ≠ 0

@[ext]
theorem ext {S T : SignedLinearRootSkeleton R}
    (hroots : S.roots = T.roots) (hscale : S.scale = T.scale) : S = T

theorem quadraticAdjoinFact {E : Intermediate F} {a : E.carrier}
    (hnsq : ¬ IsSquare a) :
    Fact (∀ r : E.carrier, r ^ 2 ≠ a + 0 * r)

theorem quadraticProjection_mul_self_eq {K L : Type*} [CommSemiring K] [Semiring L]
    [Algebra K L] {a : K}
    (e : QuadraticAlgebra K a 0 ≃ₐ[K] L) {z : L} {x y : K}
    (hz : e.symm z = (⟨x, y⟩ : QuadraticAlgebra K a 0)) :
    quadraticProjection e (z * z) = x ^ 2 + a * y ^ 2

theorem quadraticProjection_mul_self_pos {K L : Type*} [Field K] [LinearOrder K]
    [IsStrictOrderedRing K] [Field L] [Algebra K L] {a : K}
    (e : QuadraticAlgebra K a 0 ≃ₐ[K] L) {z : L}
    (ha : 0 < a) (hz : z ≠ 0) :
    0 < quadraticProjection e (z * z)

theorem nonnegative_isSquare_of_isMax
    (M : Intermediate F) (hmax : IsMax M) {a : M.carrier}
    (ha : 0 ≤ a) : IsSquare a

theorem invariant {n : ℕ} (hn : 0 < n) {p : Polynomial F}
    (hp : p ∈ oddPolynomialCone (F := F) n) :
    0 ≤ p.leadingCoeff ∧ Even p.natDegree ∧ p.natDegree < 2 * n
